const start12m = '2025-05-06';
const end12m = '2026-05-05';
const startPrior = '2024-05-06';
const endPrior = '2025-05-05';

const queries = [
  { name: 'total_12m',   body: { startDate: start12m, endDate: end12m,   dataState: 'final' } },
  { name: 'total_prior', body: { startDate: startPrior, endDate: endPrior, dataState: 'final' } },
  { name: 'top_queries', body: { startDate: start12m, endDate: end12m, dimensions: ['query'], rowLimit: 1000, dataState: 'final' } },
  { name: 'top_pages',   body: { startDate: start12m, endDate: end12m, dimensions: ['page'],  rowLimit: 500,  dataState: 'final' } },
  { name: 'by_device',   body: { startDate: start12m, endDate: end12m, dimensions: ['device'],  dataState: 'final' } },
  { name: 'by_country',  body: { startDate: start12m, endDate: end12m, dimensions: ['country'], rowLimit: 30,  dataState: 'final' } },
  { name: 'by_month',    body: { startDate: start12m, endDate: end12m, dimensions: ['date'],    rowLimit: 400, dataState: 'final' } }
];

return queries.map(q => ({ json: { name: q.name, body: JSON.stringify(q.body) } }));

const all = $input.all();
const names = $('Build Queries').all();
const r = {};
for (let i = 0; i < all.length; i++) {
  r[names[i].json.name] = all[i].json;
}

// --- Totals 12m vs prior ---
const cur  = (r.total_12m?.rows  || [{}])[0] || {};
const prev = (r.total_prior?.rows || [{}])[0] || {};

const fmt2 = n => Number(n || 0).toFixed(2);
const pct  = (a, b) => b > 0 ? Math.round(((a - b) / b) * 100) : null;

const totals = {
  clicks_12m:       cur.clicks       || 0,
  impressions_12m:  cur.impressions  || 0,
  ctr_12m:          Number((cur.ctr       || 0) * 100).toFixed(2),
  position_12m:     fmt2(cur.position),
  clicks_prior:     prev.clicks      || 0,
  impressions_prior:prev.impressions || 0,
  ctr_prior:        Number((prev.ctr      || 0) * 100).toFixed(2),
  position_prior:   fmt2(prev.position),
  yoy_clicks_pct:   pct(cur.clicks || 0, prev.clicks || 0),
  yoy_imp_pct:      pct(cur.impressions || 0, prev.impressions || 0)
};

// --- Top 30 queries ---
const topQueries = (r.top_queries?.rows || []).slice(0, 30).map(row => ({
  query:       row.keys[0],
  clicks:      row.clicks,
  impressions: row.impressions,
  ctr:         Number(row.ctr * 100).toFixed(2),
  position:    Number(row.position).toFixed(1)
}));

// --- Question queries (AEO) ---
const questionWords = /^(qué|que|cómo|como|por qué|por que|dónde|donde|cuándo|cuando|quién|quien|cuál|cual|cuanto|cuánto|es |son |tiene|hay |puedo|puedes|puede|sirve|vale|funciona|ayuda|se puede|diferencia|ventajas|beneficios|mejor|tipos|lista|pasos|ejemplo)/i;
const allQueries = (r.top_queries?.rows || []).map(row => ({
  query:       row.keys[0],
  clicks:      row.clicks,
  impressions: row.impressions,
  ctr:         Number(row.ctr * 100).toFixed(2),
  position:    Number(row.position).toFixed(1)
}));
const aeoQueries = allQueries.filter(q => questionWords.test(q.query)).slice(0, 30);

// --- Position buckets ---
const posGroups = { top3: 0, pos4_10: 0, pos11_20: 0, pos21_50: 0, pos51plus: 0 };
for (const row of (r.top_queries?.rows || [])) {
  const p = row.position;
  if (p <= 3)       posGroups.top3++;
  else if (p <= 10) posGroups.pos4_10++;
  else if (p <= 20) posGroups.pos11_20++;
  else if (p <= 50) posGroups.pos21_50++;
  else              posGroups.pos51plus++;
}

// --- Top 20 pages ---
const topPages = (r.top_pages?.rows || []).slice(0, 20).map(row => ({
  page:        row.keys[0],
  clicks:      row.clicks,
  impressions: row.impressions,
  ctr:         Number(row.ctr * 100).toFixed(2),
  position:    Number(row.position).toFixed(1)
}));

// --- Device breakdown ---
const devices = (r.by_device?.rows || []).map(row => ({
  device:      row.keys[0],
  clicks:      row.clicks,
  impressions: row.impressions,
  ctr:         Number(row.ctr * 100).toFixed(2),
  position:    Number(row.position).toFixed(1)
}));

// --- Country breakdown ---
const countries = (r.by_country?.rows || []).slice(0, 10).map(row => ({
  country:     row.keys[0],
  clicks:      row.clicks,
  impressions: row.impressions
}));

// --- Monthly trend (aggregate by month) ---
const monthMap = {};
for (const row of (r.by_month?.rows || [])) {
  const m = row.keys[0].slice(0, 7);
  if (!monthMap[m]) monthMap[m] = { clicks: 0, impressions: 0, posSum: 0, days: 0 };
  monthMap[m].clicks      += row.clicks;
  monthMap[m].impressions += row.impressions;
  monthMap[m].posSum      += row.position;
  monthMap[m].days        += 1;
}
const monthly = Object.keys(monthMap).sort().map(m => ({
  month: m,
  clicks: monthMap[m].clicks,
  impressions: monthMap[m].impressions,
  avg_position: Number(monthMap[m].posSum / monthMap[m].days).toFixed(1)
}));

return [{ json: {
  site: 'https://online.ulatina.cr/',
  period: '2025-05-06 a 2026-05-05',
  totals,
  top_queries:    topQueries,
  aeo_queries:    aeoQueries,
  position_distribution: posGroups,
  top_pages:      topPages,
  devices,
  countries,
  monthly_trend:  monthly,
  total_unique_queries: (r.top_queries?.rows || []).length,
  total_unique_pages:   (r.top_pages?.rows || []).length
} }];
